sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.metro-home {
    max-width: 900px;
    margin: 50px auto;
    padding: 20px;
    text-align: center;
}

.metro-home h1 {
    font-size: 32px;
    margin-bottom: 10px;
}

.subtitle {
    font-size: 16px;
    margin-bottom: 35px;
}

.metro-actions {
    display: flex;
    justify-content: center;
    gap: 24px;
    flex-wrap: wrap;
}

.metro-card {
    width: 320px;
    padding: 30px;
    background: #ffffff;
    border: 1px solid #dddddd;
    border-radius: 12px;
    text-decoration: none;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08);
    transition: 0.2s;
}

.metro-card:hover {
    text-decoration: none;
    box-shadow: 0 6px 18px rgba(0,0,0,0.15);
    transform: translateY(-2px);
}

.metro-card h3 {
    margin-top: 0;
}
